  if sum(a)>8:
   subs=itertools.product(*[[b for b in range(x+1) if b&x==b] for x in a]);rows.append(sum(1<<index[b] for b in subs))
 rows += [1<<i for i,w in enumerate(weights) if w>334]
 basis={}
 for row in rows:
  while row:
