  S=set(support);table=[int(x in S) for x in range(1<<15)]
  for i in range(15):
   for x in range(1<<15):
    if x>>i&1:table[x]^=table[x^(1<<i)]
  assert max(x.bit_count() for x,v in enumerate(table) if v)<=8
